42	/** Normalize URL: prepend https:// if missing */
43	function normalizeUrl(str: string): string {
44	  const trimmed = str.trim();
45	  if (!trimmed) return trimmed;
46	  if (/^https?:\/\//i.test(trimmed)) return trimmed;
47	  return `https://${trimmed}`;
48	}
