50	  const [scoreFilter, setScoreFilter] = useState("all");
51	  const [sortBy, setSortBy] = useState("newest");
52	
53	  const filtered = useMemo(() => {
54	    let scans = [...MOCK_SCANS];
55	
56	    // Search — matches URL, hostname, and page title
57	    if (search) {
58	      const q = search.toLowerCase();
59	      scans = scans.filter((s) =>
60	        s.url.toLowerCase().includes(q) ||
61	        (s.page_title?.toLowerCase().includes(q) ?? false)
62	      );
63	    }
64	
65	    // Status filter
66	    if (statusFilter !== "all") {
67	      scans = scans.filter((s) => s.status === statusFilter);
68	    }
69	
70	    // Score filter
71	    if (scoreFilter !== "all") {
72	      scans = scans.filter((s) => {
73	        if (s.overall_score === null) return false;
74	        if (scoreFilter === "poor") return s.overall_score < 40;
75	        if (scoreFilter === "average") return s.overall_score >= 40 && s.overall_score < 70;
76	        if (scoreFilter === "good") return s.overall_score >= 70;
77	        return true;
78	      });
79	    }
80	
81	    // Sort
82	    scans.sort((a, b) => {
83	      if (sortBy === "newest") return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
84	      if (sortBy === "oldest") return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
85	      if (sortBy === "score-high") return (b.overall_score ?? 0) - (a.overall_score ?? 0);
86	      if (sortBy === "score-low") return (a.overall_score ?? 0) - (b.overall_score ?? 0);
87	      return 0;
88	    });
89	
90	    return scans;
91	  }, [search, statusFilter, scoreFilter, sortBy]);
